  }

  protected dueByOf(c: Claim): string {
    return c.dueBy;
  }

  protected overdueOf(c: Claim): boolean {
    return overdue(c, this.today());
  }

  protected deferredOf(c: Claim): boolean {
    return deferred(c, this.today());
  }

